insert into programs(id,lesson_id,title,days,times,minutes,axis,body,how,uses_exercise) values ('p_sailing','b4','نية التنظيف الطاقي',7,array['22:00']::text[],5,'spirit','«أنا – وفقًا للتالي – أضع النية الواضحة لاستعادة تناغمي مع جسدي ورسالته في التجسد الحالي، كما تم تصميمه من قبل ذاتي العليا قبل التجسد الحالي.. أزل كل الحواجز والمعيقات من جسدي، سواء التي قمت بخلقها في التجسد الحالي أو أي تجسد سابق، في هذا البعد أو أي بعد آخر، بوعي أو بغير وعي، وقم بمسح كل الطاقات السلبية الناتجة عن تلك الحواجز والمعيقات غير المتوافقة مع التصميم الأصلي لنسختي الحالية المتفق عليها في عالم الروح. أضع هذه النية قاصدًا بها الخير لكل الموجودات، واثقًا من وصولها بكل البهجة والفرحة الممكنة.. ليكن الأمر كذلك.. شكرًا، شكرًا، شكرًا»','كررها 7 أيام على الأقل بعد أول دخول للسجلات.',null) on conflict (id) do update set title=excluded.title,days=excluded.days,times=excluded.times,minutes=excluded.minutes,body=excluded.body,how=excluded.how,uses_exercise=excluded.uses_exercise;
insert into programs(id,lesson_id,title,days,times,minutes,axis,body,how,uses_exercise) values ('p_vows','b7','نية تنظيف العهود قبل النوم',21,array['22:30']::text[],5,'spirit','نية «بروتوكول تنظيف البلوكات من السجلات الأكاشية»، وتذكر فيها كل عهد ومكان تأثيره في الجسد والشاكرا.','كل ليلة قبل النوم، 21 ليلة.',null) on conflict (id) do update set title=excluded.title,days=excluded.days,times=excluded.times,minutes=excluded.minutes,body=excluded.body,how=excluded.how,uses_exercise=excluded.uses_exercise;
insert into programs(id,lesson_id,title,days,times,minutes,axis,body,how,uses_exercise) values ('p_bathwave','b7','جملي الإيجابية (BATHWAVE)',21,array['07:30','22:00']::text[],5,'mind','«أنا أقدر، أنا سوف، أنا الآن …» وانت بتمرّر إيدك على مسار الكون الصغير.','قبل النوم وعند الاستيقاظ، 21 يوم. ولو السلوك رجع خلال اليوم، 9 مرات.','ex_bathwave') on conflict (id) do update set title=excluded.title,days=excluded.days,times=excluded.times,minutes=excluded.minutes,body=excluded.body,how=excluded.how,uses_exercise=excluded.uses_exercise;
